CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Fused kernel: BN eval + scale + row-wise softmax over [N, C] float32 tensors.
// One block per row; threads cooperate over the C dimension.
// Vectorized float4 fast path when C%4==0 and pointers are 16-byte aligned.

// Helper: warp-level max reduce
__device__ __forceinline__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    return val;
}

// Helper: warp-level sum reduce
__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

__global__ void bn_scale_softmax_kernel_vec4(
    const float* __restrict__ x,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int N,
    int C,
    float eps,
    int scale_size) {

    extern __shared__ float smem[];

    int row = blockIdx.x;
    if (row >= N) return;

    const float4* x_row4   = reinterpret_cast<const float4*>(x   + row * C);
    float4*       out_row4 = reinterpret_cast<float4*>(out + row * C);
    const float4* bw4 = reinterpret_cast<const float4*>(bn_weight);
    const float4* bb4 = reinterpret_cast<const float4*>(bn_bias);
    const float4* rm4 = reinterpret_cast<const float4*>(running_mean);
    const float4* rv4 = reinterpret_cast<const float4*>(running_var);

    int tid = threadIdx.x;
    int bdx = blockDim.x;
    int C4  = C >> 2;  // C / 4

    float sc0 = (scale_size == 1) ? scale[0] : 0.0f;

    // Pass 1: BN + scale via float4, compute per-thread max
    float thread_max = -3.402823466e+38f;
    for (int i = tid; i < C4; i += bdx) {
        float4 xv  = x_row4[i];
        float4 rwv = rm4[i];
        float4 rvv = rv4[i];
        float4 gwv = bw4[i];
        float4 btv = bb4[i];

        float s0, s1, s2, s3;
        if (scale_size == 1) {
            s0 = s1 = s2 = s3 = sc0;
        } else {
            const float4* sc4 = reinterpret_cast<const float4*>(scale);
            float4 sv = sc4[i];
            s0 = sv.x; s1 = sv.y; s2 = sv.z; s3 = sv.w;
        }

        float4 ov;
        ov.x = (((xv.x - rwv.x) * rsqrtf(rvv.x + eps)) * gwv.x + btv.x) * s0;
        ov.y = (((xv.y - rwv.y) * rsqrtf(rvv.y + eps)) * gwv.y + btv.y) * s1;
        ov.z = (((xv.z - rwv.z) * rsqrtf(rvv.z + eps)) * gwv.z + btv.z) * s2;
        ov.w = (((xv.w - rwv.w) * rsqrtf(rvv.w + eps)) * gwv.w + btv.w) * s3;
        out_row4[i] = ov;

        thread_max = fmaxf(thread_max, fmaxf(fmaxf(ov.x, ov.y), fmaxf(ov.z, ov.w)));
    }

    // Block reduction for max: warp shuffle + shared mem
    thread_max = warp_reduce_max(thread_max);
    int warp_id = tid >> 5;
    int lane_id = tid & 31;
    int nwarps  = bdx >> 5;
    if (lane_id == 0) smem[warp_id] = thread_max;
    __syncthreads();
    float row_max;
    if (tid < nwarps) {
        float wval = smem[tid];
        wval = warp_reduce_max(wval);
        if (tid == 0) smem[0] = wval;
    }
    __syncthreads();
    row_max = smem[0];
    __syncthreads();

    // Pass 2: exp(x - max) via float4, per-thread sum
    float thread_sum = 0.0f;
    for (int i = tid; i < C4; i += bdx) {
        float4 ov = out_row4[i];
        ov.x = expf(ov.x - row_max);
        ov.y = expf(ov.y - row_max);
        ov.z = expf(ov.z - row_max);
        ov.w = expf(ov.w - row_max);
        out_row4[i] = ov;
        thread_sum += ov.x + ov.y + ov.z + ov.w;
    }

    // Block reduction for sum
    thread_sum = warp_reduce_sum(thread_sum);
    if (lane_id == 0) smem[warp_id] = thread_sum;
    __syncthreads();
    float row_sum;
    if (tid < nwarps) {
        float wval = smem[tid];
        wval = warp_reduce_sum(wval);
        if (tid == 0) smem[0] = wval;
    }
    __syncthreads();
    row_sum = smem[0];
    __syncthreads();

    // Pass 3: normalize via float4
    float inv_sum = 1.0f / row_sum;
    for (int i = tid; i < C4; i += bdx) {
        float4 ov = out_row4[i];
        ov.x *= inv_sum;
        ov.y *= inv_sum;
        ov.z *= inv_sum;
        ov.w *= inv_sum;
        out_row4[i] = ov;
    }
}

__global__ void bn_scale_softmax_kernel_scalar(
    const float* __restrict__ x,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int N,
    int C,
    float eps,
    int scale_size) {

    extern __shared__ float smem[];

    int row = blockIdx.x;
    if (row >= N) return;

    const float* x_row   = x   + row * C;
    float*       out_row = out + row * C;

    int tid = threadIdx.x;
    int bdx = blockDim.x;

    // Pass 1: BN + scale
    float thread_max = -3.402823466e+38f;
    for (int c = tid; c < C; c += bdx) {
        float mean  = running_mean[c];
        float var   = running_var[c];
        float gamma = bn_weight[c];
        float beta  = bn_bias[c];
        float s     = (scale_size == 1) ? scale[0] : scale[c];
        float val   = ((x_row[c] - mean) * rsqrtf(var + eps)) * gamma + beta;
        val *= s;
        out_row[c]  = val;
        thread_max  = fmaxf(thread_max, val);
    }

    smem[tid] = thread_max;
    __syncthreads();
    for (int stride = bdx >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) smem[tid] = fmaxf(smem[tid], smem[tid + stride]);
        __syncthreads();
    }
    float row_max = smem[0];
    __syncthreads();

    // Pass 2: exp
    float thread_sum = 0.0f;
    for (int c = tid; c < C; c += bdx) {
        float val = expf(out_row[c] - row_max);
        out_row[c] = val;
        thread_sum += val;
    }

    smem[tid] = thread_sum;
    __syncthreads();
    for (int stride = bdx >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) smem[tid] += smem[tid + stride];
        __syncthreads();
    }
    float row_sum = smem[0];
    __syncthreads();

    // Pass 3: normalize
    float inv_sum = 1.0f / row_sum;
    for (int c = tid; c < C; c += bdx) {
        out_row[c] *= inv_sum;
    }
}

torch::Tensor bn_scale_softmax_cuda(
    torch::Tensor x,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    torch::Tensor scale,
    double eps) {

    int N = x.size(0);
    int C = x.size(1);
    int scale_size = (int)scale.numel();

    auto out = torch::empty_like(x);

    // Use 256 threads; each block handles one row.
    const int threads = 256;
    const int blocks  = N;
    int nwarps = threads / 32;

    // Check alignment for float4 path: C divisible by 4, all row pointers 16-byte aligned
    bool use_vec4 = (C % 4 == 0)
        && ((reinterpret_cast<uintptr_t>(x.data_ptr<float>())           & 15) == 0)
        && ((reinterpret_cast<uintptr_t>(out.data_ptr<float>())         & 15) == 0)
        && ((reinterpret_cast<uintptr_t>(bn_weight.data_ptr<float>())   & 15) == 0)
        && ((reinterpret_cast<uintptr_t>(bn_bias.data_ptr<float>())     & 15) == 0)
        && ((reinterpret_cast<uintptr_t>(running_mean.data_ptr<float>())& 15) == 0)
        && ((reinterpret_cast<uintptr_t>(running_var.data_ptr<float>()) & 15) == 0)
        && (scale_size == 1 || ((reinterpret_cast<uintptr_t>(scale.data_ptr<float>()) & 15) == 0));

    if (use_vec4) {
        // Shared mem: one float per warp for reduction
        size_t smem_bytes = nwarps * sizeof(float);
        bn_scale_softmax_kernel_vec4<<<blocks, threads, smem_bytes>>>(
            x.data_ptr<float>(),
            bn_weight.data_ptr<float>(),
            bn_bias.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            scale.data_ptr<float>(),
            out.data_ptr<float>(),
            N, C,
            (float)eps,
            scale_size
        );
    } else {
        size_t smem_bytes = threads * sizeof(float);
        bn_scale_softmax_kernel_scalar<<<blocks, threads, smem_bytes>>>(
            x.data_ptr<float>(),
            bn_weight.data_ptr<float>(),
            bn_bias.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            scale.data_ptr<float>(),
            out.data_ptr<float>(),
            N, C,
            (float)eps,
            scale_size
        );
    }

    return out;
}
