import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p84_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor bn_scale_softmax_cuda(
    torch::Tensor x,
    torch::Tensor mul,
    torch::Tensor add);

torch::Tensor bn_scale_softmax(
    torch::Tensor x,
    torch::Tensor mul,
    torch::Tensor add) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(mul.is_cuda(), "mul must be a CUDA tensor");
    TORCH_CHECK(mul.is_contiguous(), "mul must be contiguous");
    TORCH_CHECK(mul.dtype() == torch::kFloat32, "mul must be float32");
    TORCH_CHECK(add.is_cuda(), "add must be a CUDA tensor");
    TORCH_CHECK(add.is_contiguous(), "add must be contiguous");
    TORCH_CHECK(add.dtype() == torch::kFloat32, "add must be float32");
    TORCH_CHECK(mul.numel() == x.size(1), "mul size must match x columns");
    TORCH_CHECK(add.numel() == x.size(1), "add size must match x columns");
    return bn_scale_softmax_cuda(x, mul, add);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("bn_scale_softmax", &bn_scale_softmax, "Fused BN+Scale+Softmax (CUDA)");
}
