CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void bn_scale_softmax_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mul,
    const float* __restrict__ add,
    float* __restrict__ out,
    int N,
    int C) {

    extern __shared__ float smem[];

    int row = blockIdx.x;
    if (row >= N) return;

    const float* x_row = x + row * C;
    float* out_row = out + row * C;

    int tid = threadIdx.x;
    int blockDim_x = blockDim.x;

    // Pass 1: Apply folded affine transform, write to out, find per-thread max
    float thread_max = -1e38f;
    for (int c = tid; c < C; c += blockDim_x) {
        float val = x_row[c] * mul[c] + add[c];
        out_row[c] = val;
        thread_max = fmaxf(thread_max, val);
    }

    // Block reduction for max
    float* smax = smem;
    smax[tid] = thread_max;
    __syncthreads();
    for (int stride = blockDim_x >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            smax[tid] = fmaxf(smax[tid], smax[tid + stride]);
        }
        __syncthreads();
    }
    float row_max = smax[0];
    __syncthreads();

    // Pass 2: exp(x - max), find per-thread sum
    float* ssum = smem;
    float thread_sum = 0.0f;
    for (int c = tid; c < C; c += blockDim_x) {
        float val = expf(out_row[c] - row_max);
        out_row[c] = val;
        thread_sum += val;
    }

    ssum[tid] = thread_sum;
    __syncthreads();
    for (int stride = blockDim_x >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            ssum[tid] += ssum[tid + stride];
        }
        __syncthreads();
    }
    float row_sum = ssum[0];
    __syncthreads();

    // Pass 3: normalize
    float inv_sum = 1.0f / row_sum;
    for (int c = tid; c < C; c += blockDim_x) {
        out_row[c] *= inv_sum;
    }
}

torch::Tensor bn_scale_softmax_cuda(
    torch::Tensor x,
    torch::Tensor mul,
    torch::Tensor add) {

    int N = x.size(0);
    int C = x.size(1);

    auto out = torch::empty_like(x);

    const int threads = 256;
    const int blocks = N;
    size_t smem_bytes = threads * sizeof(float);

    bn_scale_softmax_kernel<<<blocks, threads, smem_bytes>>>(
        x.data_ptr<float>(),
        mul.data_ptr<float>(),
        add.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a matrix multiplication (Gemm), Batch Normalization, scaling, and Softmax.
        """
    def __init__(self, in_features, out_features, bn_eps=1e-5, bn_momentum=0.1, scale_shape=(1,)):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.gemm = nn.Linear(in_features, out_features)
        self.bn = nn.BatchNorm1d(out_features, eps=bn_eps, momentum=bn_momentum)
        self.scale = nn.Parameter(torch.ones(scale_shape))
        self.softmax = nn.Softmax(dim=1)
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        # Use fused CUDA path when: eval mode, CUDA float32 2D contiguous tensor.
        _use_fused = (
            not self.training
            and x.is_cuda
            and x.dtype == torch.float32
            and x.dim() == 2
            and x.is_contiguous()
        )
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        x = self.gemm(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        if _use_fused:
            inv_std = torch.rsqrt(self.bn.running_var.contiguous() + self.bn.eps)
            mul = self.bn.weight.contiguous() * inv_std
            add = self.bn.bias.contiguous() - self.bn.running_mean.contiguous() * mul
            if self.scale.numel() == 1:
                scale_val = self.scale.item()
                mul = mul * scale_val
                add = add * scale_val
        else:
            mul = mul * self.scale.contiguous()
            add = add * self.scale.contiguous()
        return _stark_get_extension().bn_scale_softmax(
        x,
        mul.contiguous(),
        add.contiguous()
        )
        x = self.bn(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        x = self.scale * x
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        x = self.softmax(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_6>>>
        return x
        # <<<END_IMPROVE>>>

