// Specialized tiled kernel: C == THREADS * TILE (e.g. 8192 = 256*32).
// Each thread caches its TILE values in a register array, performing
// exactly 1 global read and 1 global write per element.
#define BN_TILE32
#define BN_THREADS 256

__global__ void bn_scale_softmax_kernel_tiled(
    const float* __restrict__ x,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int N,
    int C,
    float eps,
    int scale_size) {

    extern __shared__ float smem[];

    int row = blockIdx.x;
    if (row >= N) return;

    const float* x_row = x + row * C;
    float* out_row = out + row * C;

    int tid = threadIdx.x;

    float reg[BN_TILE];

    // Pass 1: single global read; compute BN+scale; cache in registers; find thread max.
    float s0 = (scale_size == 1) ? scale[0] : 0.0f;
    float thread_max = -3.402823466e+38f;
    #pragma unroll
    for (int i = 0; i < BN_TILE; i++) {
        int c = tid + i * BN_THREADS;
        float mean  = running_mean[c];
        float var   = running_var[c];
        float gamma = bn_weight[c];
        float beta  = bn_bias[c];
        float s     = (scale_size == 1) ? s0 : scale[c];
        float val   = fmaf(fmaf(x_row[c] - mean, rsqrtf(var + eps),0.0f) * gamma + beta, s, 0.0f);
        val = ((x_row[c] - mean) * rsqrtf(var + eps) * gamma + beta) * s;
        reg[i] = val;
        thread_max = fmaxf(thread_max, val);
    }

    float row_max = block_reduce_max(thread_max, smem);

    // In-place exp over register array; accumulate sum.
    float thread_sum = 0.0f;
    #pragma unroll
    for (int i = 0; i < BN_TILE; i++) {
        float e = expf(reg[i] - row_max);
        reg[i] = e;
        thread_sum += e;
    }

    float row_sum = block_reduce_sum(thread_sum, smem);
    float inv_sum = 1.0f / row_sum;

    // Single global write.
    #pragma unroll
    for (int i = 0; i < BN_TILE; i++) {
        out_row[tid + i * BN_THREADS] = reg[i] * inv_sum;
    }
}

// Generic fallback: recomputes BN+scale three times but handles arbitrary C.
__global__ void bn_scale_softmax_kernel_generic(
    const float* __restrict__ x,
    const float* __restrict__ bn_weight,
    const float* __restrict__ bn_bias,
    const float* __restrict__ running_mean,
    const float* __restrict__ running_var,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int N,
    int C,
    float eps,
